Translate("frFR", "dun-morogh", {
	title = "Dun Morogh",
	sections = {
		{
			title = "Résumé",
			text = [=[Dun Morogh est une terre de neige et de pierre à l'ouest de Khaz Modan, l'antique patrie des {link:dwarves}nains{/link}. Ses pics sont les plus hauts des {link:eastern-kingdoms}Royaumes de l'est{/link}, et dans le plus grand d'entre eux se trouve {link:ironforge}Ironforge{/link}, la capitale du {link:kingdom-of-ironforge}royaume d'Ironforge{/link}. Les {link:gnomes}gnomes{/link} vivaient ici eux aussi, dans la cité de {link:gnomeregan}Gnomeregan{/link} sous les collines de l'ouest. Entre les deux cités s'étendent des lacs gelés, des bois de pins et une unique et longue route à travers la neige. C'est un pays rude, et son peuple en est fier.]=],
		},
		{
			title = "Origines",
			text = [=[Les nains disent qu'ils furent façonnés dans la pierre de ces montagnes aux âges anciens, et qu'{link:ironforge}Ironforge{/link} est leur plus vieux foyer. Il y a longtemps, tous les nains étaient gouvernés depuis la cité par un seul haut roi. Quand ce roi mourut, les clans Bronzebeard, Wildhammer et {link:dark-iron-dwarves}Sombrefer{/link} se firent la guerre pour son trône, et les Bronzebeard gardèrent la montagne. Les gnomes devinrent les voisins et les amis des nains, et ils élevèrent {link:gnomeregan}Gnomeregan{/link} dans les contreforts de l'ouest. Aucune chronique ne donne l'année de fondation de l'une ou l'autre cité.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Dun Morogh est moins sûr qu'il ne l'a jamais été de mémoire d'homme. Une grande partie de l'armée du roi est loin, au service de l'{link:alliance}Alliance{/link} à l'étranger, et les montagnards qui restent sont peu nombreux. Les {link:troggs}troggs{/link} ont jailli des profondeurs, et ils tiennent désormais la Passe des {link:coldridge-valley}Frigères{/link} et les fosses de la {link:gol-bolar-quarry}Carrière de Gol'Bolar{/link}. Les {link:frostmane-trolls}trolls Frostmane{/link} tiennent leurs cavernes et leurs crêtes à l'ouest. {link:gnomeregan}Gnomeregan{/link} est perdue, et son peuple empoisonné erre devant ses portes. Des wendigos ont envahi l'antre Gris. Plus inquiétant encore, des espions du {link:dark-iron-dwarves}clan Sombrefer{/link} ont été vus à l'est, porteurs de cartes de tunnels qui mènent sous {link:ironforge}Ironforge{/link} même.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les nains d'{link:ironforge}Ironforge{/link}.{/b} Mineurs, brasseurs, éleveurs de béliers et montagnards, ils vivent à {link:kharanos}Kharanos{/link}, à {link:brewnall-village}Brassetout{/link} et dans les camps isolés des hautes terres.
• {b}Les gnomes de {link:gnomeregan}Gnomeregan{/link}.{/b} Les survivants de leur cité déchue s'abritent à Ironforge, et certains travaillent à Kharanos pour réparer le mal qui a été fait.
• {b}Les {link:frostmane-trolls}trolls Frostmane{/link}.{/b} Ils tiennent des cavernes et des crêtes à l'ouest et disputent les neiges aux nains.
• {b}Les troggs.{/b} Les troggs Rockjaw sont montés de sous la terre et attaquent désormais partout où les nains creusent.
• {b}Les wendigos et les bêtes.{/b} Wendigos, ours, sangliers et léopards des neiges parcourent les collines, et certains sont devenus trop hardis et trop grands.
• {b}Les {link:dark-iron-dwarves}Sombrefer{/link}.{/b} Une bande d'entre eux tient la {link:ironband-s-compound}Base d'Ironband{/link} à l'est, à observer et à attendre.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les Trois Marteaux.{/b} Lors de la guerre des trois clans, les Bronzebeard tinrent {link:ironforge}Ironforge{/link} et chassèrent leurs rivaux. Un traité conservé sous la cité rapporte que les Wildhammer signèrent la paix, et que les {link:dark-iron-dwarves}Sombrefer{/link} ne la signèrent pas.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Quand la {link:horde}Horde{/link} envahit Khaz Modan, Ironforge elle-même tint bon. Les nains rejoignirent l'{link:alliance}Alliance de Lordaeron{/link} et combattirent aux côtés des humains jusqu'à ce que la Horde soit brisée.
• {b}La chute de {link:gnomeregan}Gnomeregan{/link}.{/b} Les troggs surgirent sous la cité {link:gnomes}gnome{/link}. Les gnomes luttèrent pour les chasser, mais l'arme qu'ils employèrent empoisonna la cité et nombre des leurs. Les survivants s'enfuirent à Ironforge.
• {b}Aujourd'hui.{/b} Les nains affrontent à la fois les troggs, les trolls et les Sombrefer, avec la moitié de leurs forces partie à la guerre.]=],
		},
		{
			title = "Savoir des montagnes",
			text = [=[• Les Thunderbrew de {link:kharanos}Kharanos{/link} et les Barleybrew de {link:brewnall-village}Brassetout{/link} sont des familles de brasseurs rivales. Chacune croit que la bière de l'autre n'est bonne que pour les sangliers.
• Les {link:frostmane-trolls}trolls Frostmane{/link} cultivent une herbe pâle appelée shimmerweed sur les crêtes au-dessus du {link:iceflow-lake}Lac glacial{/link}, et ils l'emploient dans leurs rituels. Les nains lui ont trouvé un meilleur usage : la bière brune.
• Les montagnards d'{link:ironforge}Ironforge{/link} gravent leur nom dans la crosse de leur fusil, afin que la neige puisse dire qui elle a emporté.
• Les voleurs d'Ironforge murmurent que les chars à vapeur blindés du roi transportent le minerai et les gemmes de la {link:gol-bolar-quarry}Carrière de Gol'Bolar{/link} par une route étrangement détournée, et que quelqu'un devrait bien l'en soulager d'une petite part.]=],
		},
	},
})

Translate("frFR", "coldridge-valley", {
	title = "Vallée des Frigères",
	aliases = { "Frigères" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée des Frigères est un vallon abrité au sud-ouest de {link:dun-morogh}Dun Morogh{/link}, enclos de montagnes de tous côtés. Les nouveaux défenseurs d'{link:ironforge}Ironforge{/link} viennent ici apprendre leur métier à Anvilmar. La vallée a perdu sa paix. Des troggs Rockjaw ont submergé le camp de l'ouest et grouillent sur les collines près du lac gelé. Des {link:frostmane-trolls}trolls Frostmane{/link} tiennent une caverne au sud. La seule route pour sortir, par le tunnel de la Passe des Frigères, est désormais infestée de troggs, et un montagnard monte la garde à son entrée.]=],
		},
	},
})

Translate("frFR", "anvilmar", {
	title = "Anvilmar",
	sections = {
		{
			title = "Résumé",
			text = [=[Anvilmar est une demeure creusée profondément dans le flanc de la montagne, au fond de {link:stranglethorn-vale}la Vallée{/link} des {link:coldridge-valley}Frigères{/link}. Ici, les maîtres d'{link:ironforge}Ironforge{/link} apprennent aux jeunes à combattre, à prier et à exercer leur métier, et des fournisseurs leur donnent des vêtements chauds contre le froid. C'est aussi un refuge. Des gnomes qui ont fui le poison de {link:gnomeregan}Gnomeregan{/link} ont trouvé abri dans ses salles, et certains comptent encore ce qu'ils ont perdu sur la route.]=],
		},
	},
})

Translate("frFR", "kharanos", {
	title = "Kharanos",
	aliases = { "Distillerie Thunderbrew" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kharanos est le principal bourg de {link:dun-morogh}Dun Morogh{/link}, un groupe de maisons de pierre sur la route entre les {link:coldridge-valley}Frigères{/link} et {link:ironforge}Ironforge{/link}. En son cœur se dresse la Distillerie Thunderbrew, célèbre dans tout Khaz Modan, dont les caves sont remplies jusqu'au plafond de tonneaux de Thunder Ale. L'auberge qu'elle abrite est rarement calme. Les montagnards viennent y faire leur rapport, et {link:senir-whitebeard}Senir Whitebeard{/link} y rédige ses rapports pour le Sénat d'Ironforge. Deux gnomes du bourg travaillent à une machine qui, espèrent-ils, guérira leur peuple.]=],
		},
	},
})

Translate("frFR", "steelgrill-s-depot", {
	title = "Dépôt de Steelgrill",
	aliases = { "Dépôt Steelgrill" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Dépôt de Steelgrill se trouve juste au nord-est de {link:kharanos}Kharanos{/link}. C'est l'atelier de {link:beldin-steelgrill}Beldin Steelgrill{/link}, le meilleur mécanicien d'engins de siège des montagnes, et un repaire des pilotes de la Brigade de siège. Leurs chars à vapeur blindés portent des noms comme Jetsteam et Trollplow, et leurs pilotes s'en vantent comme d'autres nains se vantent de leurs béliers. Le dépôt entend beaucoup de ce qui se passe sur les routes, et c'est le rapport d'un montagnard, ici, qui attira pour la première fois les regards vers un étrange feu de camp au-dessus de {link:gol-bolar-quarry}Gol'Bolar{/link}.]=],
		},
	},
})

Translate("frFR", "the-grizzled-den", {
	title = "L'antre Gris",
	aliases = { "Antre Gris" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'antre Gris est une caverne dans les collines à l'ouest de {link:kharanos}Kharanos{/link}. Ses tunnels étaient autrefois une riche source de minerai, et les mineurs de Kharanos y travaillaient. Puis les wendigos sortirent de leurs propres cavernes et l'envahirent. Les mineurs s'enfuirent et abandonnèrent leurs chargements. Un montagnard nommé Cornelius y entra pour mesurer la gravité de la situation et n'en ressortit jamais. Tout au fond demeure un wendigo bruyant et sauvage appelé Frosthowl.]=],
		},
	},
})

Translate("frFR", "chill-breeze-valley", {
	title = "Vallée de la bise",
	sections = {
		{
			title = "Résumé",
			text = [=[La Vallée de la bise s'ouvre à l'ouest de {link:dun-morogh}Dun Morogh{/link}, entre {link:kharanos}Kharanos{/link} et les collines de {link:gnomeregan}Gnomeregan{/link}. Sa partie est est très fréquentée, car la route de la Passe des {link:coldridge-valley}Frigères{/link} la traverse. Peu de gens s'aventurent de bon gré dans ses recoins plus tranquilles. Là, un grand wendigo appelé Old Icebeard tient une caverne, et il emporta un jour tout le garde-manger du trappeur Tundra MacGrann, qui campe non loin avec une mauvaise jambe et le ventre vide.]=],
		},
	},
})

Translate("frFR", "brewnall-village", {
	title = "Brassetout",
	aliases = { "Brassetout" },
	sections = {
		{
			title = "Résumé",
			text = [=[Brassetout se trouve sur la rive ouest du {link:iceflow-lake}Lac glacial{/link}. C'est le foyer de la famille Barleybrew, des brasseurs qui expérimentent sans crainte et parfois sans succès. Leur Evershine brûle si fort que les pilotes de siège le versent dans leurs chaudières. Les Barleybrew n'aiment guère les Thunderbrew de {link:kharanos}Kharanos{/link}, et ils ne dédaignent pas de jouer quelques mauvais tours dans la cave de leurs rivaux. Des pêcheurs travaillent le lac à côté d'eux, et les {link:frostmane-trolls}trolls Frostmane{/link} les observent depuis le sud-ouest.]=],
		},
	},
})

Translate("frFR", "iceflow-lake", {
	title = "Lac glacial",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac glacial s'étend au nord de {link:dun-morogh}Dun Morogh{/link}, à l'ouest d'{link:ironforge}Ironforge{/link}, gelé une grande partie de l'année. Une rivière de glace y descend depuis le pont au nord de {link:kharanos}Kharanos{/link}. Des loups chassent sur l'île en son centre. Les pêcheurs de {link:brewnall-village}Brassetout{/link} percent des trous dans la glace et attendent des jours au-dessus de leurs lignes, et ils maudissent les wendigos qui volent le peu qu'ils attrapent.]=],
		},
	},
})

Translate("frFR", "frostmane-hold", {
	title = "Repaire des Frostmane",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Repaire des Frostmane est la grande caverne des {link:frostmane-trolls}trolls Frostmane{/link}, au sud-ouest de {link:brewnall-village}Brassetout{/link}. Chasseurs de têtes, écorcheurs, arpenteurs des neiges et lanceurs d'ombre y vivent en nombre, au point d'effrayer même le {link:dwarves}nain{/link} envoyé les compter. Le Repaire est le cœur de la puissance des Frostmane à {link:dun-morogh}Dun Morogh{/link}. Les nains ont tenté d'apprendre ce que les trolls y préparent, et leurs rapports ont causé autant de troubles au Sénat que dans la neige.]=],
		},
	},
})

Translate("frFR", "shimmer-ridge", {
	title = "Crête scintillante",
	sections = {
		{
			title = "Résumé",
			text = [=[La Crête scintillante est une chaîne de hautes collines au nord de {link:dun-morogh}Dun Morogh{/link}, près du {link:iceflow-lake}Lac glacial{/link} et à l'ouest des Portes d'{link:ironforge}Ironforge{/link}. Les {link:frostmane-trolls}trolls Frostmane{/link} y ont des camps reliés par un pont, et leurs voyants y entretiennent des paniers de shimmerweed. L'herbe joue un rôle dans leurs rites. Pour les brasseurs de {link:brewnall-village}Brassetout{/link}, elle a un autre usage, et ils paient bien quiconque grimpe sur la crête pour la voler.]=],
		},
	},
})

Translate("frFR", "gates-of-gnomeregan", {
	title = "Portes de Gnomeregan",
	sections = {
		{
			title = "Résumé",
			text = [=[Au nord de {link:brewnall-village}Brassetout{/link}, les collines de l'ouest de {link:dun-morogh}Dun Morogh{/link} s'élèvent jusqu'aux portes de {link:gnomeregan}Gnomeregan{/link}. C'était autrefois un pays animé de machines et de villages gnomes. À présent, les pompes et les filtres sont brisés, et les gnomes qui restent sont empoisonnés, malades et hostiles, errant devant les portes de la cité qu'ils n'ont pas pu sauver. Parmi eux, un espion {link:dwarves}nain{/link} aux desseins louches se cache sous un déguisement. Des gnomes qui ont fui disent que de précieuses archives de leur peuple gisent encore ici, enfouies dans la neige.]=],
		},
	},
})

Translate("frFR", "gol-bolar-quarry", {
	title = "Carrière de Gol'Bolar",
	aliases = { "Gol'Bolar" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Carrière de Gol'Bolar est une grande fosse à ciel ouvert à l'est de {link:dun-morogh}Dun Morogh{/link}, où les mineurs du roi taillent le minerai et la pierre. Quand ils creusèrent profond, les troggs Rockjaw jaillirent de la roche, brisèrent les machines et chassèrent les mineurs de la fosse. À présent, le contremaître fulmine, un sénateur d'{link:ironforge}Ironforge{/link} paie pour les têtes de troggs, et le maître carrier espère que personne n'apprendra que les troggs sont partis avec sa poudre explosive. Depuis les Collines de Tundrid, au-dessus, un étranger Wildhammer veille sur tout cela.]=],
		},
	},
})

Translate("frFR", "amberstill-ranch", {
	title = "Ferme des Amberstill",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme des Amberstill se trouve au bord de la route, à l'est de {link:kharanos}Kharanos{/link}. La famille Amberstill élève les grands béliers des montagnes qui portent les nains d'{link:ironforge}Ironforge{/link}, et leurs troupeaux sont la fierté de {link:dun-morogh}Dun Morogh{/link}. Les béliers de la ferme partent désormais pour l'expédition d'{link:alterac-mountains}Alterac{/link}, et il leur faut des selles faites des plus belles peaux de léopard. Le troupeau s'est aussi trouvé un chasseur : la bête {link:vagash}Vagash{/link}, qui a son repaire sur les pentes au-dessus et descend la nuit.]=],
		},
	},
})

Translate("frFR", "misty-pine-refuge", {
	title = "Refuge de Brumepins",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge de Brumepins est une maison isolée dans les collines du nord de {link:dun-morogh}Dun Morogh{/link}, à l'est des Portes d'{link:ironforge}Ironforge{/link}. Le père {link:father-gavin}Gavin{/link} de l'{link:argent-dawn}Aube d'argent{/link} l'a réparée et garde son âtre allumé pour tout voyageur surpris par le froid. Les montagnes alentour sont devenues dangereuses. Un éboulement venu des pics a réveillé des esprits de glace, et le plus grand d'entre eux semble apporter tempêtes et nouveaux éboulements partout où il va.]=],
		},
	},
})

Translate("frFR", "helm-s-bed-lake", {
	title = "Lac du Lit d'Helm",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac du Lit d'Helm se trouve à l'extrême sud-est de {link:dun-morogh}Dun Morogh{/link}, près des cols qui mènent au {link:loch-modan}Loch Modan{/link}. Son eau est presque entièrement gelée, et le pays alentour est sauvage et désert. Des troggs Rockjaw rôdent sur ses rives. Dans les collines au nord, un pilote de siège attend près de deux engins un ami parti seul à la recherche d'un minerai rare. Cet ami était Mori Hildelve, et un grand ours appelé Mangeclaw le trouva le premier.]=],
		},
	},
})

Translate("frFR", "ironband-s-compound", {
	title = "Base d'Ironband",
	sections = {
		{
			title = "Résumé",
			text = [=[La Base d'Ironband est une maison et sa cour au sud du {link:helm-s-bed-lake}Lac du Lit d'Helm{/link}, à l'est de {link:dun-morogh}Dun Morogh{/link}. Ses propriétaires nains l'ont quittée. Des nains {link:dark-iron-dwarves}Sombrefer{/link} la tiennent à présent, menés par un capitaine nommé Beld, et ils attaquent quiconque s'approche. Le voyant de la terre Wildhammer {link:earthseer-farsen}Farsen{/link} croit que ce ne sont pas de simples pillards. Les cartes prises sur leurs morts montrent des tunnels qui courent loin sous terre et se rejoignent sous {link:ironforge}Ironforge{/link}.]=],
		},
	},
})

Translate("frFR", "frostmane-trolls", {
	title = "Trolls Frostmane",
	aliases = { "Frostmane", "trolls Frostmane", "tribu Frostmane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Frostmane sont une tribu de {link:trolls}trolls{/link} qui vit dans les neiges de {link:dun-morogh}Dun Morogh{/link}. Ils sont farouches et secrets, et ils disputent ces montagnes aux nains. Aucune chronique ne dit quand ils arrivèrent ici.]=],
		},
		{
			title = "Leurs terres",
			text = [=[Leur plus grande place forte est le {link:frostmane-hold}Repaire des Frostmane{/link}, une caverne au sud-ouest de {link:brewnall-village}Brassetout{/link}. Ils ont aussi des camps sur la {link:shimmer-ridge}Crête scintillante{/link} et une caverne au sud de {link:stranglethorn-vale}la Vallée{/link} des {link:coldridge-valley}Frigères{/link}, où vivent les jeunes de la tribu. Leurs guerriers sont des chasseurs de têtes et des arpenteurs des neiges. Leurs voyants et leurs lanceurs d'ombre pratiquent une magie qui leur est propre, et ils récoltent le shimmerweed pour leurs rituels.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le Sénat d'{link:ironforge}Ironforge{/link} a fort à faire avec les troggs, et il préférerait ne pas penser du tout aux trolls. Deux frères de la famille Whitebeard furent envoyés mesurer l'ampleur réelle de la menace. {link:grelin-whitebeard}Grelin{/link} jugea que les trolls des {link:coldridge-valley}Frigères{/link} étaient peu nombreux. {link:senir-whitebeard}Senir{/link} trouva le {link:frostmane-hold}Repaire des Frostmane{/link} plein de trolls. Entre les deux rapports se pose la question de savoir ce que les nains peuvent se permettre d'ignorer. Dans les Frigères, un troll appelé {link:grik-nir-the-cold}Grik'nir le Froid{/link} a volé aux nains plus qu'un journal : il leur a montré que les Frostmane les observent.]=],
		},
	},
})

Translate("frFR", "gnomeregan-exiles", {
	title = "Exilés de Gnomeregan",
	aliases = { "exilés de Gnomeregan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Exilés de Gnomeregan sont les gnomes qui ont survécu à la chute de leur cité. C'est un peuple sans foyer. La plupart vivent à {link:ironforge}Ironforge{/link}, où le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} leur a fait place à {link:tinker-town}Tinker Town{/link}, mais ils sont dispersés à travers {link:dun-morogh}Dun Morogh{/link} et au-delà.]=],
		},
		{
			title = "Après la chute",
			text = [=[Les troggs surgirent sous {link:gnomeregan}Gnomeregan{/link}, et les gnomes les repoussèrent avec une arme de leur invention. Tout tourna horriblement mal. La cité fut empoisonnée, et nombre de ses habitants furent changés en lépreux malades et privés de raison qui errent encore devant ses portes. Les autres s'enfuirent dans la neige avec ce qu'ils pouvaient porter. Certains perdirent tout face aux trolls en chemin. D'autres laissèrent derrière eux les archives de leurs familles, leurs inventions et leur savoir-faire.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les exilés n'ont pas renoncé. À {link:kharanos}Kharanos{/link}, {link:razzle-sprysprocket}Razzle Sprysprocket{/link} et Ozzie Togglevolt construisent une machine qui, espèrent-ils, rendra leur état aux gnomes empoisonnés. À {link:ironforge}Ironforge{/link}, les bricoleurs de {link:gnomeregan}Gnomeregan{/link} renvoient de courageux étrangers dans la cité pour sauver son savoir perdu. Le Grand Artisan {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} jure que son peuple reprendra son foyer au traître qui le tient.]=],
		},
	},
})

Translate("frFR", "sten-stoutarm", {
	title = "Sten Stoutarm",
	subtitle = "Fournisseur des Frigères",
	found = "Devant les portes d'Anvilmar",
	hint = [=[Parlez au nain qui accueille les nouveaux venus aux portes d'Anvilmar.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Stoutarm" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sten Stoutarm monte la garde aux portes d'Anvilmar et accueille ceux qui viennent servir dans les {link:coldridge-valley}Frigères{/link}. Il a une façon pratique de les accueillir. Une paire de gants chauds est son premier cadeau, et de la viande de loup est son prix. Dans une vallée aussi froide, estime-t-il, mieux vaut perdre une matinée de chasse qu'un doigt.]=],
		},
		{
			title = "Importance",
			text = [=[Sten est le premier {link:dwarves}nain{/link} que rencontrent la plupart des nouveaux venus dans les {link:coldridge-valley}Frigères{/link}. Il fait suivre les lettres le long de la route et veille à ce qu'aucune recrue d'{link:ironforge}Ironforge{/link} ne parte dans la neige sans être préparée.]=],
		},
	},
	mentions = {
		{ text = "Fournisseurs nains" },
		{
			text = [=[Livraison du courrier de {link:stranglethorn-vale}la Vallée{/link} des {link:coldridge-valley}Frigères{/link}]=],
		},
	},
	bonds = {
		{ id = "balir-frosthammer", name = "Balir Frosthammer", note = "monte la garde à ses côtés" },
		{ id = "grelin-whitebeard", name = "Grelin Whitebeard", note = "reçoit le courrier de la vallée" },
