			hint = "Récupérez ce que les trolls ont pris à Grelin.",
			text = [=[Le voleur était un grand troll aux marques étranges sur le visage et la peau. Quand le journal revint, Grelin put achever son travail et déclarer que les ennuis de la vallée avec les trolls étaient bien maîtrisés. Il prit soin d'envoyer le rapport à {link:senir-whitebeard}Senir{/link} par des mains fiables, et non par son apprenti.]=],
		},
	},
	mentions = {
