	allegiance = "Clan Wildhammer",
	aliases = { "Farsen" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le voyant de la terre Farsen est un {link:dwarves}nain{/link} Wildhammer du {link:aerie-peak}Nid-de-l'Aigle{/link} qui a établi son camp dans les collines au-dessus de la {link:gol-bolar-quarry}Carrière de Gol'Bolar{/link}. Il vint à {link:dun-morogh}Dun Morogh{/link} en voyageur, et il y trouva les {link:dark-iron-dwarves}Sombrefer{/link}. Grâce à sa vision lointaine, il peut regarder la terre d'en haut comme le fait un griffon, et ce qu'il voit le trouble : des espions Sombrefer, aussi nombreux que la vermine.]=],
		},
		{
			title = "Importance",
			text = [=[Farsen donne à {link:ironforge}Ironforge{/link} le premier avertissement de l'incursion {link:dark-iron-dwarves}Sombrefer{/link} sous la cité. Il appelle aussi le {link:magni-bronzebeard}roi Magni{/link} un vieil ami, et le roi se souvient de lui avec chaleur.]=],
		},
	},
	chapters = {
		{
			title = "La carte sous la montagne",
			hint = "Apportez à Farsen ce que portaient les Sombrefer.",
			text = [=[Parmi les morts {link:dark-iron-dwarves}Sombrefer{/link} se trouvait une carte de tunnels et de routes profondes, qui convergeaient toutes vers un même point sous {link:ironforge}Ironforge{/link}. Farsen la lut et y vit une force d'éclaireurs, et non une bande de voleurs. Il fit dire de descendre dans les caveaux sous la cité avant que les Sombrefer ne puissent atteindre leur but.]=],
		},
	},
	mentions = {
		{ text = "Un visiteur à {link:dun-morogh}Dun Morogh{/link}" },
		{ text = "La veille de Farsen" },
		{ text = "Tuer dans l'œuf" },
